# Generate `lean/SeedKernel/Heisenberg/TrialData.lean`, the data behind the kernel-checked
# trial-state bound (`lean/SeedKernel/Heisenberg/Trial.lean`).
#
#   julia --project=models/lean_seeds models/lean_seeds/scripts/trial/generate.jl          # write
#   julia --project=models/lean_seeds models/lean_seeds/scripts/trial/generate.jl --check  # compare
#
# The data are untrusted: Lean rechecks every identity. This script also checks them in exact
# integer arithmetic and compares the reduced traces with the upstream trial certificates, so that
# a regenerated file is known to pass before Lean is run.
include(joinpath(@__DIR__, "..", "..", "src", "trial.jl"))
using .TrialSeed
using SparseArrays, LinearAlgebra

const LEAN_FILE = joinpath(TrialSeed.REPO, "lean", "SeedKernel", "Heisenberg", "TrialData.lean")
const LENGTHS = (72, 120)

"Hex literal of `Σᵢ xs[i] 2^(w i)` (lane 0 least significant)."
function hexpack(xs, w)
    x = big(0)
    for v in Iterators.reverse(xs)
        @assert 0 <= v < big(2)^w
        x = (x << w) + v
    end
    return "0x" * string(x, base=16)
end

lanewidth(xs) = max(1, maximum(ndigits(BigInt(v), base=2) for v in xs; init=1))

"Offset encoding of a signed integer list: offset, lane width, literal."
function offset_code(xs)
    β = maximum(abs, xs; init=big(0))
    shifted = [BigInt(v) + β for v in xs]
    w = lanewidth(shifted)
    return β, w, hexpack(shifted, w)
end

"Unsigned encoding of a natural-number list: lane width, literal."
function nat_code(xs)
    w = lanewidth(xs)
    return w, hexpack(xs, w)
end

"Lean list literal of naturals or integers (one line per item for long literals)."
leanlist(xs) = "[" * join(string.(xs), ",\n  ") * "]"

"""
Sparse groups `rows[r] = [(col, val), …]` (0-based) as count, index and value codes.
"""
function group_code(rows)
    counts = [length(r) for r in rows]
    idx = [c for r in rows for (c, _) in r]
    vals = [v for r in rows for (_, v) in r]
    return counts, idx, vals
end

function generate()
    ops = TrialSeed.operators()
    bs = TrialSeed.blocks(ops)
    tw = TrialSeed.intertwiner(ops, bs)
    W, V, c = BigInt.(tw.W), tw.V, tw.c
    n = size(W, 1)
    B = TrialSeed.block_matrix(bs, :t)
    C = TrialSeed.block_matrix(bs, :o)
    @assert BigInt.(ops.T) * W == W * B
    @assert BigInt.(ops.O) * W == W * C
    @assert V * W == c * sparse(BigInt(1) * I, n, n)

    # Reduced traces against the upstream certificates.
    traces = Dict(N => TrialSeed.block_traces(bs, N) for N in LENGTHS)
    totals = Dict{Int,Tuple{BigInt,BigInt}}()
    for N in LENGTHS
        U = sum((2b.J + 1) * x.U for (b, x) in zip(bs, traces[N]))
        Vt = sum((2b.J + 1) * x.V for (b, x) in zip(bs, traces[N]))
        expected = TrialSeed.read_exact_json(joinpath(TrialSeed.SOURCE,
            "evidence/trials/certificate$N.json"))
        @assert U == TrialSeed.integer(expected[N == 72 ? "one_bond_energy_numerator" : "U"])
        @assert Vt == TrialSeed.integer(expected[N == 72 ? "norm" : "V"])
        @assert Vt > 0 && 500000U < -700741Vt
        totals[N] = (U, Vt)
    end

    io = IOBuffer()
    p(xs...) = println(io, xs...)
    p("""/-
Copyright (c) 2026 thermal-mpo-gap contributors. All rights reserved.
Released under Apache 2.0 license as described in the file LICENSE.
Authors: thermal-mpo-gap contributors
-/
import SeedKernel.Heisenberg.TrialLinear

/-!
# Data of the trial-state reduction (generated)

GENERATED by `models/lean_seeds/scripts/trial/generate.jl`; do not edit. Every number here is
untrusted input: the files importing it recheck each identity in the kernel.

* `trialMatrixCode s`: the recipe matrices `A s` (offset code, row-major), for the cross-check
  `trialA_eq_code` against the Lean recipe.
* Blocks `b = 0, …, $(length(bs) - 1)`: spin `blockJ`, multiplicity `blockDim`, first global
  column `blockStart`; the blocks `tᵦ`, `oᵦ` (offset codes, row-major).
* The intertwiner `W` (columns `(b, k, c)`, local index `k mᵦ + c`) grouped by the doubled
  index `p = 26a + b`, and `V = c W⁻¹` grouped by column, with `c = trialScale`.
* `blockTrace N b = (tr (tᵦ^N), tr (tᵦ^(N-2) oᵦ))` for `N = 72, 120`.
-/

namespace SeedKernel.Trial

-- The hexadecimal literals cannot be wrapped.
set_option linter.style.longLine false
""")
    # The recipe matrices, row-major per s.
    for (k, s) in enumerate(-1:1)
        β, w, lit = offset_code(vec(permutedims(ops.A[s])))
        p("/-- `A $(k - 1)` (physical `m = $s`): offset $β, lane width $w. -/")
        p("def trialMatrixCode$(k - 1) : ℕ × ℕ × ℕ := ($β, $w,\n  $lit)")
        p()
    end
    p("/-- Spin `J` of each block. -/")
    p("def blockJ : List ℕ := ", string([b.J for b in bs]))
    p("/-- Multiplicity `mᵦ` (size of `tᵦ`) of each block. -/")
    p("def blockDim : List ℕ := ", string([size(b.t, 1) for b in bs]))
    p("/-- First global column `∑_{b' < b} (2J_{b'}+1) m_{b'}` of each block. -/")
    p("def blockStart : List ℕ := ", string(tw.offsets))
    p()
    for (name, which) in (("t", :t), ("o", :o))
        codes = [offset_code(vec(permutedims(which == :t ? b.t : b.o))) for b in bs]
        p("/-- `$(name)ᵦ` as (offset, lane width, row-major code). -/")
        p("def $(name)Code : List (ℕ × ℕ × ℕ) := [")
        p(join(["  ($(x[1]), $(x[2]),\n   $(x[3]))" for x in codes], ",\n"))
        p("]")
        p()
    end
    # W grouped by the doubled index, per block, with local columns.
    wcodes, vcodes = String[], String[]
    for (bi, b) in enumerate(bs)
        m = size(b.t, 1)
        width = (2b.J + 1) * m
        cols = tw.offsets[bi]+1:tw.offsets[bi]+width
        Wb = W[:, cols]
        rows = [[(j - 1, Wb[pidx, j]) for j in 1:width if !iszero(Wb[pidx, j])] for pidx in 1:n]
        counts, idx, vals = group_code(rows)
        wc, cl = nat_code(counts)
        wi, il = nat_code(idx)
        β, wv, vl = offset_code(vals)
        push!(wcodes, "  ⟨$(length(idx)), ($wc, $cl), ($wi, $il), ($β, $wv, $vl)⟩")
        Vb = V[cols, :]
        vrows = [[(pidx - 1, Vb[j, pidx]) for pidx in 1:n if !iszero(Vb[j, pidx])] for j in 1:width]
        counts, idx, vals = group_code(vrows)
        wc, cl = nat_code(counts)
        wi, il = nat_code(idx)
        β, wv, vl = offset_code(vals)
        push!(vcodes, "  ⟨$(length(idx)), ($wc, $cl), ($wi, $il), ($β, $wv, $vl)⟩")
    end
    p("/-- `W` restricted to the columns of each block, grouped by the doubled index (676 groups of",
        "\n(local column, value)): total count, counts code, columns code, values offset code. -/")
    p("def wCode : List SparseCode := [\n", join(wcodes, ",\n"), "]")
    p()
    p("/-- `V = c W⁻¹` restricted to the rows of each block, grouped by local row (groups of",
        "\n(doubled index, value)). -/")
    p("def vCode : List SparseCode := [\n", join(vcodes, ",\n"), "]")
    p()
    p("/-- The scale `c` of `V W = c 1`. -/")
    p("def trialScale : ℕ := $c")
    p()
    for N in LENGTHS
        p("/-- `(tr (tᵦ^$N), tr (tᵦ^$(N - 2) oᵦ))` for each block. -/")
        p("def blockTrace$N : List (ℤ × ℤ) := [")
        p(join(["  ($(x.V),\n   $(x.U))" for x in traces[N]], ",\n"))
        p("]")
        p()
        U, Vt = totals[N]
        p("/-- `U = tr (T^$(N - 2) O)` and `V = tr (T^$N)` of the trial state (upstream values). -/")
        p("def trialU$N : ℤ := $U")
        p("def trialV$N : ℤ := $Vt")
        p()
    end
    p("end SeedKernel.Trial")
    return String(take!(io))
end

function main()
    text = generate()
    if "--check" in ARGS
        @assert isfile(LEAN_FILE) && read(LEAN_FILE, String) == text "TrialData.lean is stale"
        println("PASS TrialData.lean regenerates identically")
    else
        write(LEAN_FILE, text)
        println("wrote ", LEAN_FILE, " (", sizeof(text), " bytes)")
    end
end

main()
